export enum Team {
    BLUE = 0,
    RED = 1
}

export enum Role {
    TANK = 'TANK',
    WARRIOR = 'WARRIOR',
    RANGER = 'RANGER',
    MAGE = 'MAGE',
    SUPPORT = 'SUPPORT'
}

export enum MovementType {
    GROUND = 0,
    FLYING = 1
}

export enum AnimState {
    IDLE = 0,
    COMBAT_IDLE = 1,
    ATTACK = 2,
    HIT = 3,
    DEAD = 4,
    STUN = 5,
    MOVE = 6
}

export interface Hex {
    q: number;
    r: number;
}

export interface Point {
    x: number;
    y: number;
}

// Scene / Environment Types
export interface SceneTheme {
    id: string;
    name: string;
    background: string; // Sky Top Color
    horizon: string;    // Sky Bottom/Horizon Color (New)
    fogColor: string;   // Low-lying fog color (New)
    textureType: 'VOID' | 'FOREST' | 'ICE' | 'MAGMA' | 'DESERT';
    obstacleStyle: string; 
    hexStroke: string; 
    ambientType: 'NONE' | 'SNOW' | 'ASH' | 'SPORES' | 'RAIN' | 'EMBER';
    ambientColor: string;
    bgFeature: 'NONE' | 'SKY_RIVER' | 'AURORA' | 'CANOPY' | 'HEAT_WAVE' | 'DUNES';
}

// Data Models
export interface Skill {
    id: string;
    tag: 'BASIC' | 'ACTIVE' | 'ULT';
    role: Role;
    team?: Team; // Optional: If specified, only this team can learn it
    name: string;
    desc?: string; // For Tooltips
    range: number;
    cast: number;
    cd: number;
    cost: number;
    gain: number;
    type: 'SINGLE' | 'AOE';
    aoeRadius?: number; // Default 1 if not specified
    power: number;
    color: string;

    // Control Effects (Slot 1)
    // Updated with New CC Types + TAUNT
    ccType?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE' | 'SLOW' | 'ROOT' | 'FEAR' | 'CONFUSION' | 'TAUNT';
    ccDur?: number;
    ccForce?: number;

    // Control Effects (Slot 2)
    ccType2?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE' | 'SLOW' | 'ROOT' | 'FEAR' | 'CONFUSION' | 'TAUNT';
    ccDur2?: number;
    ccForce2?: number;

    // Special Combat Effects (Slot 1)
    effectType?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal?: number; // e.g. 0.5 for 50% Vamp, 1.5 for 50% bonus Execute dmg

    // Special Combat Effects (Slot 2)
    effectType2?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal2?: number;

    projectileSpeed?: number; // 0 = Instant
    visual?: 'ARROW' | 'FIREBALL' | 'BOLT' | 'SLASH' | 'SMASH' | 'BEAM' | 'BOMB';
}

export interface UnitStats {
    role: Role;
    maxHp: number;
    maxMp: number;
    moveSpeed: number; // Tiles per second. 1.0 = 1 tile/sec
    movementType: MovementType; // Ground or Flying
}

export interface ObstacleDef {
    id: string;
    name: string;
    blocksVision: boolean;
    blocksMovement: boolean;
    blocksFlying?: boolean; // New: If true, blocks even flying units (High Towers/Pillars)
}

// Logic State Types
export enum NodeState {
    SUCCESS = 'S',
    FAILURE = 'F',
    RUNNING = 'R'
}

export type LogActionType = 'MOVE' | 'CAST' | 'HIT' | 'DECISION' | 'DEATH' | 'SYSTEM' | 'HEAL' | 'CC' | 'HAZARD';

export interface LogEntry {
    id: string;
    time: string;
    turn: number; // Battle tick or frame count
    agentId: string; // "Who"
    team: Team | undefined;
    location: string; // "Where" (e.g., "(10, 5)")
    actionType: LogActionType;
    actionName: string; // "What" (e.g., "Fireball", "MoveTo")
    targetInfo?: string; // "To Whom" (e.g., "Tank-A @ (12,5)")
    detail: string; // Narrative details
    visualColor?: string; // For UI highlighting

    // Legacy support fields (optional)
    action?: string;
    target?: string;
    loc?: string;
}

export interface Projectile {
    id: string;
    x: number;
    y: number;
    startX: number; // New: For Height Interpolation
    startY: number; // New: For Height Interpolation
    startZ?: number; // New: Initial height offset (for flying units)
    targetId: string;
    targetPos: Point;
    speed: number;
    skill: Skill;
    sourceId: string;
    team: Team;
    trail: Point[];
}

// NEW: Per-Tile Hazard
export interface GroundHazard {
    id: string;
    q: number;
    r: number;
    type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC';
    duration: number; // Seconds remaining
    sourceId: string;
    team: Team;
    color: string;
    power: number; // Damage per tick
    interval: number; // Tick rate
    timer: number; // Current tick timer
}

// Event System (Bridge between Logic and Visuals)
export type GameEventType = 'DAMAGE' | 'HEAL' | 'CC_APPLIED' | 'CAST_START' | 'CAST_FINISH' | 'PROJECTILE_SPAWN' | 'PROJECTILE_HIT' | 'DEATH' | 'SPAWN' | 'VISUAL_BEAM' | 'CAST_BREAK' | 'VISUAL_SLASH' | 'KILL' | 'IMPACT_AOE';

export interface GameEvent {
    type: GameEventType;
    pos: Point;
    value?: number; // Damage amount, heal amount, etc.
    text?: string; // For specialized text
    color?: string;
    skill?: Skill;
    sourceId?: string;
    targetId?: string;
    team?: Team;
}

// Tooling
export enum ToolType {
    SELECT = 'SELECT',
    ADD_BLUE = 'ADD_BLUE',
    ADD_RED = 'ADD_RED',
    OBSTACLE = 'OBSTACLE',
    DELETE = 'DELETE'
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    // Stats
    public hp: number = 100;
    public maxHp: number = 100;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0; 
    public moveSpeedMult: number = 1.0; 
    public jump: number = 1; // Vertical mobility tier
    public weight: number = 1; // Knockback resistance
    public movementType: MovementType = MovementType.GROUND;

    // Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0; 
    public curCDs: number[] = [0, 0, 0];

    // State / AI
    public isMoving: boolean = false;
    public path: Hex[] = []; 
    public trajectory: Hex[] = []; 
    public moveProgress: number = 0;
    public facing: number = 1; 
    public target: Agent | null = null;
    public targetHex: Hex | null = null; 
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // Status Effects
    public stunTimer: number = 0;
    public stunMax: number = 0; 

    public banishTimer: number = 0;
    public banishMax: number = 0; 

    public silenceTimer: number = 0;
    public silenceMax: number = 0; 

    // --- NEW CC TIMERS ---
    public rootTimer: number = 0;
    public rootMax: number = 0;

    public slowTimer: number = 0;
    public slowMax: number = 0;

    public fearTimer: number = 0;
    public fearMax: number = 0;
    public fearSourceId: string | null = null; // To run away from

    public confusionTimer: number = 0;
    public confusionMax: number = 0;

    public tauntTimer: number = 0; // NEW: Taunt duration
    public tauntTargetId: string | null = null; // NEW: Who taunted me?
    // ---------------------

    public banished: boolean = false;

    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    // Diminishing Returns (DR) System
    // Tracks current stack count per CC type (STUN, SILENCE, etc.)
    public drStacks: Record<string, number> = {}; 
    // Tracks time until DR resets for that type
    public drTimers: Record<string, number> = {}; 

    // Visual State
    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    // Lifecycle
    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public hitFlashTimer: number = 0;

    // Physics
    public physics = { 
        x: 0, y: 0, z: 0,          
        vx: 0, vy: 0, vz: 0,       
        angle: 0, vAngle: 0   
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR; 
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0; 
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.stunMax = 0;
        this.banishTimer = 0;
        this.banishMax = 0;
        this.silenceTimer = 0;
        this.silenceMax = 0;

        // Reset New CCs
        this.rootTimer = 0; this.rootMax = 0;
        this.slowTimer = 0; this.slowMax = 0;
        this.fearTimer = 0; this.fearMax = 0; this.fearSourceId = null;
        this.confusionTimer = 0; this.confusionMax = 0;

        this.tauntTimer = 0; this.tauntTargetId = null;

        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        // Reset DR
        this.drStacks = {};
        this.drTimers = {};

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5; 

        this.target = null;
        this.targetHex = null;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
    }
}

import { Agent, GameEngine } from "../game";
import { AnimState } from "../../types";
import { COMBAT_PARAM } from "../../constants";

export class StatusSystem {

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Cooldowns
        agent.curCDs = agent.curCDs.map(c => Math.max(0, c - dt));

        // 2. Diminishing Returns (DR)
        for (const type in agent.drTimers) {
            if (agent.drTimers.hasOwnProperty(type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 3. Spawn Animation
        if (agent.spawnTimer > 0) {
            agent.spawnTimer -= dt;
        }

        // 4. Banish Logic (Gatekeeper)
        if (agent.banishTimer > 0) {
            agent.banishTimer -= dt;
            if (agent.banishTimer <= 0) {
                agent.banished = false;
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            } else {
                if (agent.visualStatus === 'POLYMORPH') {
                    // Sheep keep ticking
                } else {
                    return; // Pause processing
                }
            }
        }

        // 5. Hard & Soft CC Timers
        if (agent.stunTimer > 0) agent.stunTimer -= dt;
        if (agent.silenceTimer > 0) agent.silenceTimer -= dt;

        // --- NEW CC TIMERS ---
        if (agent.rootTimer > 0) agent.rootTimer -= dt;
        if (agent.fearTimer > 0) agent.fearTimer -= dt;
        if (agent.confusionTimer > 0) agent.confusionTimer -= dt;

        if (agent.tauntTimer > 0) {
            agent.tauntTimer -= dt;
            if (agent.tauntTimer <= 0) {
                agent.tauntTargetId = null;
            }
        }

        if (agent.slowTimer > 0) {
            agent.slowTimer -= dt;
            // Apply Slow Effect directly here to ensure it sticks
            // NOTE: Charge effects might override this in MovementSystem, handled by multiplication priority
            // But base speed modifier logic resides here.
            // However, agent.moveSpeedMult is reset in MovementSystem after move.
            // We need a persistent way. 
            // Better strategy: MovementSystem checks slowTimer before moving.
        }

        if (agent.fearTimer <= 0) agent.fearSourceId = null;

        // 6. Visual State Reset
        if (agent.visualStatus === 'FROZEN' && agent.stunTimer <= 0) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'POLYMORPH' && !agent.banished) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'STASIS' && !agent.banished) agent.visualStatus = 'NONE';

        // 7. DoT (Damage over Time)
        if (agent.dotTimer > 0) {
            agent.dotTimer -= dt;
            agent.hp -= agent.dotDmg * dt;
            if (Math.random() < 0.05) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.round(agent.dotDmg), 
                    color: '#10b981' 
                });
                agent.hitFlashTimer = 0.1;
            }
        }

        // 8. HoT (Heal over Time)
        if (agent.hotTimer > 0) {
            agent.hotTimer -= dt;
            agent.hp = Math.min(agent.maxHp, agent.hp + agent.hotVal * dt);
            if (Math.random() < 0.05) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.round(agent.hotVal), 
                    color: '#86efac' 
                });
            }
        }

        // 9. Animation State Reset
        // Condition: Not Stunned, Not Banished, Not Moving, Not Casting
        // AND Not currently in Hit Recovery
        if (agent.stunTimer <= 0 && agent.banishTimer <= 0 && !agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {

    // =========================================================================================
    // 🏹 RANGE CALCULATION (High Ground Bonus)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Bonus: +1 Range per Block Height advantage
        // Only applies if attacker is higher. No penalty for low ground (to avoid frustration).
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    // =========================================================================================
    // 🎯 TARGET ACQUISITION
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        // TAUNT LOGIC: If taunted, forced to target the teaser
        if (a.tauntTimer > 0 && a.tauntTargetId) {
            const taunter = engine.agents.find(ag => ag.id === a.tauntTargetId);
            if (taunter && taunter.hp > 0 && !taunter.banished) {
                a.target = taunter;
                return; // Override all other logic
            } else {
                // Taunter dead or gone? Break taunt early
                a.tauntTargetId = null;
                a.tauntTimer = 0;
            }
        }

        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        // 0. Taunt Override: If taunted, can ONLY cast if target matches taunter
        // Usually Taunt implies Silence for skills, but we handle that in Condition checks "SkillReady" logic 
        // or effectively by forcing target here.
        if (source.tauntTimer > 0 && source.tauntTargetId) {
            const taunter = engine.agents.find(a => a.id === source.tauntTargetId);
            if (taunter && taunter.hp > 0) {
                // We return the taunter as the ONLY valid target.
                // The Movement system will try to move to it.
                // The Cast action will check range.
                return { targetAgent: taunter, targetHex: null };
            }
        }

        // 1. Special Case: Silence Logic (Prioritize Casters/Ults)
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= this.getEffectiveRange(source, a.q, a.r, skill.range, engine)
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        // 2. AOE Logic (Find Best Cluster)
        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            // Rough search: Range + Radius + small buffer.
            const searchDist = skill.range + 5; 

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                // Range Check: Can source cast to this ground position?
                const effRange = this.getEffectiveRange(source, h.q, h.r, skill.range, engine);
                if (HexUtils.dist(source, h) > effRange) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        // 3. Default Single Target Logic (Nearest)
        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                // Check against Height-Aware Range
                const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);
                if (d <= effRange && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { BLOCK_HEIGHT, COMBAT_PARAM } from "../../../constants";

export class SkillResolutionSystem {

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interruption Check: Stun, Banish, Death, Fear, Confusion, Taunt (Indirectly via Action Lock)
        // Root/Slow do NOT interrupt casting
        if (a.stunTimer > 0 || a.banished || a.hp <= 0 || a.fearTimer > 0 || a.confusionTimer > 0) {
            this.handleInterruption(a, engine);
            return;
        }

        // Taunt interrupts casting if the target is NOT the taunter
        if (a.tauntTimer > 0 && a.tauntTargetId) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            // If casting a beneficial skill or targeting someone else, break it
            // Simple logic: Taunt breaks ANY current cast to force retargeting next tick
            if (currentSkill) {
                this.handleInterruption(a, engine);
                return;
            }
        }

        if (a.silenceTimer > 0 && a.castingSkillIdx !== -1) {
            const currentSkill = a.skills[a.castingSkillIdx];
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            this.completeCast(a, engine);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            const skillName = s.name;
            engine.log(a, 'CC', '中斷', skillName, '詠唱被打斷');

            let centerPos = { x: a.px, y: a.py };
            if (s.type === 'AOE') {
                const centerHex = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : {q: a.q, r: a.r});
                centerPos = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(centerHex.q, centerHex.r);
                centerPos.y -= h;
            } else {
                centerPos.y -= engine.map.getTerrainHeight(a.q, a.r);
            }

            engine.events.push({
                type: 'CAST_BREAK',
                pos: centerPos,
                value: s.aoeRadius || 1, 
                color: s.color,
                skill: s
            });
        }

        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.IDLE); 
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;

        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd;

        if (s.projectileSpeed && s.projectileSpeed > 0) {
             engine.combat.spawnProjectile(a, s, engine);
        } else {
            this.executeInstantSkill(a, s, engine);
        }

        a.castingSkillIdx = -1;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 

        if (skill.type === 'AOE') {
            const centerHex = source.targetHex || (source.target ? { q: source.target.q, r: source.target.r } : { q: source.q, r: source.r });
            targets = engine.agents.filter(e => 
                e.team !== source.team && e.hp > 0 && !e.banished && HexUtils.dist(centerHex!, e) <= radius
            );

            const p = HexUtils.toPx(centerHex!.q, centerHex!.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };

            if (skill.ccType === 'DOT' || skill.ccType === 'PULL' || skill.name.includes("霧") || skill.name.includes("雨") || skill.name.includes("域")) {
                const affectedTiles = HexUtils.range(centerHex!, radius);
                const dur = skill.ccDur || 5.0;
                let hType: any = 'GENERIC';
                if (skill.ccType === 'DOT') hType = 'POISON';
                if (skill.name.includes('火') || skill.name.includes('Lava')) hType = 'FIRE';
                if (skill.name.includes('冰') || skill.name.includes('Frost')) hType = 'ICE';
                if (skill.ccType === 'PULL') hType = 'GRAVITY';

                affectedTiles.forEach(tile => {
                    engine.map.addHazard(
                        tile.q, tile.r, 
                        hType, 
                        dur, 
                        source.id, 
                        source.team, 
                        skill.color,
                        (skill.power * 0.2) || 10, 
                        0.5 
                    );
                });
            }

            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effectiveRange) targets = [source.target];
            }
        }

        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 2) engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            else if (dist === 2) engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });

            this.resolveHit(source, t, skill, origin, engine);
        });

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const calc = this.calculateDamageValues(source, target, skill);
        const oldHp = Math.ceil(target.hp);

        if (calc.finalDamage >= target.hp && !engine.isFinishing) {
            const alliesAlive = engine.agents.filter(a => a.team === target.team && a.hp > 0 && a.id !== target.id).length;
            if (alliesAlive === 0) {
                engine.timeScale = 0.1; 
                engine.targetTimeScale = 0.1; 
            }
        }

        target.hp = Math.min(target.maxHp, target.hp - calc.finalDamage);

        if (calc.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + calc.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: calc.vampAmount, color: '#86efac' });
        }

        if (calc.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - calc.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + calc.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${calc.manaBurn} MP`, color: "#3b82f6" });
        }

        if (calc.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + calc.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${calc.manaRestore} MP`, color: "#60a5fa" });
        }

        if (calc.finalDamage > 0) {
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const impulse = this.calculateImpulseVector(originPx, {x: target.px, y: target.py}, calc.finalDamage);
            target.physics.vx += impulse.x;
            target.physics.vy += impulse.y;
            target.physics.vAngle += (Math.random() - 0.5) * 0.5;
        }

        if (calc.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });

        engine.events.push({
            type: calc.finalDamage > 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: -calc.finalDamage,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        engine.log(source, calc.finalDamage > 0 ? 'HIT' : 'HEAL', skill.name, target.id, `${calc.finalDamage > 0 ? '造成傷害' : '回復生命'} ${Math.abs(calc.finalDamage)} (HP: ${oldHp} -> ${newHp})`);

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type || type === 'NONE') return;

        const { effectiveDuration, isImmune, isReduced } = this.calculateControlDuration(target, type, dur || 0);

        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫!", color: "#9ca3af" });
            return;
        }
        if (isReduced) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py - 20}, text: "抵抗", color: "#9ca3af" });
        }

        if (['STUN', 'SILENCE', 'BANISH', 'ROOT', 'FEAR', 'CONFUSION', 'TAUNT'].includes(type)) {
            target.drStacks[type] = (target.drStacks[type] || 0) + 1;
            target.drTimers[type] = COMBAT_PARAM.DR_RESET_TIME;
        }

        let statusText = "";
        let statusColor = "#fff";

        if (type === 'STUN') {
            if (effectiveDuration > target.stunTimer) {
                target.stunTimer = effectiveDuration;
                target.stunMax = effectiveDuration;
            }
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            statusText = "暈眩"; statusColor = "#facc15"; 
            if (this.isIceSkill(skill)) target.visualStatus = 'FROZEN';

        } else if (type === 'SILENCE') {
            if (effectiveDuration > target.silenceTimer) {
                target.silenceTimer = effectiveDuration;
                target.silenceMax = effectiveDuration;
            }
            statusText = "沉默"; statusColor = "#94a3b8"; 

        } else if (type === 'ROOT') {
            if (effectiveDuration > target.rootTimer) {
                target.rootTimer = effectiveDuration;
                target.rootMax = effectiveDuration;
            }
            target.isMoving = false; // Immediate stop
            statusText = "定身"; statusColor = "#4ade80"; // Greenish for vines/earth

        } else if (type === 'SLOW') {
            if (effectiveDuration > target.slowTimer) {
                target.slowTimer = effectiveDuration;
                target.slowMax = effectiveDuration;
            }
            statusText = "緩速"; statusColor = "#93c5fd";

        } else if (type === 'FEAR') {
            if (effectiveDuration > target.fearTimer) {
                target.fearTimer = effectiveDuration;
                target.fearMax = effectiveDuration;
                target.fearSourceId = source.id; // Run away from caster
            }
            target.castingSkillIdx = -1;
            statusText = "恐懼"; statusColor = "#a855f7";

        } else if (type === 'CONFUSION') {
            if (effectiveDuration > target.confusionTimer) {
                target.confusionTimer = effectiveDuration;
                target.confusionMax = effectiveDuration;
            }
            target.castingSkillIdx = -1;
            statusText = "混亂"; statusColor = "#f472b6";

        } else if (type === 'TAUNT') {
            // New: Taunt Logic
            if (effectiveDuration > target.tauntTimer) {
                target.tauntTimer = effectiveDuration;
                target.tauntTargetId = source.id;
            }
            target.castingSkillIdx = -1; // Break current cast
            statusText = "嘲諷"; statusColor = "#ef4444";

        } else if (type === 'BANISH') {
            if (effectiveDuration > target.banishTimer) {
                target.banishTimer = effectiveDuration;
                target.banishMax = effectiveDuration;
            }
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            statusText = "放逐"; statusColor = "#c084fc"; 

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; statusText = "變形";
            } else if (skill.name.includes("無敵") || skill.name.includes("金身") || skill.name.includes("干涉")) {
                target.visualStatus = 'STASIS'; statusText = "無敵";
                target.stunTimer = 0; target.silenceTimer = 0; target.dotTimer = 0;
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py - 20}, text: "淨化!", color: "#fff" });
            } else {
                target.visualStatus = 'NONE';
            }

        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
            if (result.applied) {
                statusText = type === 'PULL' ? "牽引" : "擊退";
                statusColor = "#fff";
                target.setAnim(AnimState.HIT);
                target.physics.vz += 200;
            } else {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
            }

        } else if (type === 'DOT') {
            target.dotDmg = force || 5;
            target.dotTimer = effectiveDuration || 3;
            statusText = "中毒"; statusColor = "#10b981";

        } else if (type === 'HOT') {
            target.hotVal = force || 5;
            target.hotTimer = effectiveDuration || 3;
            statusText = "再生"; statusColor = "#86efac";
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
        }
    }

    private calculateDamageValues(source: Agent, target: Agent, skill: Skill) {
        let rawDmg = skill.power;
        let isExecute = false;

        const isExec1 = skill.effectType === 'EXECUTE';
        const isExec2 = skill.effectType2 === 'EXECUTE';
        if ((isExec1 || isExec2) && target.hp < target.maxHp * COMBAT_PARAM.EXECUTE_THRESHOLD) {
            const multiplier = (isExec1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_EXECUTE_MULTIPLIER;
            rawDmg = Math.floor(rawDmg * multiplier);
            isExecute = true;
        }

        let vampAmount = 0;
        const isVamp1 = skill.effectType === 'VAMP';
        const isVamp2 = skill.effectType2 === 'VAMP';
        if (rawDmg > 0 && (isVamp1 || isVamp2)) {
            const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_VAMP_PCT;
            vampAmount = Math.floor(rawDmg * vampPct);
        }

        let manaBurn = 0;
        let manaRestore = 0;
        const e1 = skill.effectType; const e2 = skill.effectType2;
        const v1 = skill.effectVal; const v2 = skill.effectVal2;

        if (e1 === 'MANA_BURN') manaBurn += (v1 || COMBAT_PARAM.MANA_BURN_DEFAULT);
        if (e2 === 'MANA_BURN') manaBurn += (v2 || COMBAT_PARAM.MANA_BURN_DEFAULT);

        if (e1 === 'MANA_RESTORE') manaRestore += (v1 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        if (e2 === 'MANA_RESTORE') manaRestore += (v2 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);

        return { finalDamage: rawDmg, isExecute, vampAmount, manaBurn, manaRestore };
    }

    private calculateControlDuration(target: Agent, type: string, baseDuration: number) {
        const isHardCC = ['STUN', 'SILENCE', 'BANISH', 'ROOT', 'FEAR', 'CONFUSION', 'TAUNT'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false, isReduced: false };

        const currentStack = target.drStacks[type] || 0;
        let drMultiplier = Math.pow(0.5, currentStack);
        if (drMultiplier < 0.2) drMultiplier = 0;

        return {
            effectiveDuration: baseDuration * drMultiplier,
            isImmune: drMultiplier === 0,
            isReduced: drMultiplier < 1.0 && drMultiplier > 0
        };
    }

    private calculateImpulseVector(origin: {x: number, y: number}, target: {x: number, y: number}, damage: number) {
        const dx = target.x - origin.x;
        const dy = target.y - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);

        if (len <= 0) {
            const ang = Math.random() * Math.PI * 2;
            return {
                x: Math.cos(ang) * COMBAT_PARAM.HIT_IMPULSE_MIN,
                y: Math.sin(ang) * COMBAT_PARAM.HIT_IMPULSE_MIN
            };
        }

        const force = Math.min(COMBAT_PARAM.HIT_IMPULSE_MAX, Math.max(COMBAT_PARAM.HIT_IMPULSE_MIN, damage * 1.5));

        return {
            x: (dx / len) * force,
            y: (dy / len) * force
        };
    }

    private calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        // Can't knockback rooted units
        if (target.rootTimer > 0) return { applied: false };

        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 
        const tilesToPush = Math.max(0, rawForce - resistance);

        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

        let currentH = {q: target.q, r: target.r};
        let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
        let finalH = currentH;

        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN = null;
            let bestDot = -99;

            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                const dot = nDir.x * vector.x + nDir.y * vector.y;

                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }

            if (bestN) {
                if (!engine.isValid(bestN.q, bestN.r)) break; 
                if (engine.isBlocked(bestN.q, bestN.r, target.id, target.movementType)) break;
                if (type === 'PULL' && bestN.q === source.q && bestN.r === source.r) break;

                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > currentHeight + BLOCK_HEIGHT * 2) break; 
                if (nextHeight < currentHeight - BLOCK_HEIGHT * 3) break; 

                currentH = bestN;
                currentHeight = nextHeight;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            if (target.isMoving) {
                target.isMoving = false;
                target.path = [];
            }
            return { applied: true };
        }
        return { applied: false };
    }

    private isIceSkill(skill: Skill): boolean {
        const c = skill.color.toLowerCase();
        const n = skill.name;
        return c.includes('blue') || c.includes('#60a5fa') || c.includes('#e0f2fe') || 
               n.includes("冰") || n.includes("凍") || n.includes("雪");
    }
}

