import { Agent, GameEngine } from "../game";
import { NodeState, Skill } from "../../types";
import { HexUtils } from "../utils";

// Types needed for the Builder
export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "HasTarget": (a, engine) => {
        engine.movement.updateTarget(a, engine);
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    // Skill Checks
    "SkillReady": (a, _, args) => {
        const idx = args.slot; // 0=Ult, 1=Active, 2=Basic
        const s = a.skills[idx];

        // Basic Validity
        if (!s || a.curCDs[idx] > 0 || a.mp < s.cost || a.castingSkillIdx !== -1) {
            return false;
        }

        // --- 🛑 CRITICAL FIX: CC LOCKOUT ---
        // Prevent AI from trying to cast Active/Ult skills while under Soft CC that interrupts casting.
        // This stops the "Cast -> Interrupt -> Cast" infinite loop.
        const isControlImpaired = a.tauntTimer > 0 || a.fearTimer > 0 || a.confusionTimer > 0;

        if (s.tag !== 'BASIC') {
            if (a.silenceTimer > 0) return false;
            if (isControlImpaired) return false; // AI cannot use complex skills when mentally compromised
        }

        return true;
    },

    // Tactical Checks
    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const result = engine.movement.calculateOptimalTarget(a, skill, engine);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            const effRange = engine.movement.getEffectiveRange(a, a.target.q, a.target.r, skill.range, engine);
            return HexUtils.dist(a, result.targetAgent) <= effRange;
        } 
        else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        // Re-verify target existence
        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.movement.getEffectiveRange(a, tQ, tR, skill.range, engine);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        return dist <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        // More descriptive idle status
        if (a.stunTimer > 0) a.btStatus = "暈眩";
        else if (a.tauntTimer > 0) a.btStatus = "被嘲諷";
        else if (a.fearTimer > 0) a.btStatus = "恐懼";
        else a.btStatus = a.silenceTimer > 0 ? "沉默" : "待機";

        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        if (!a.skills[idx]) return NodeState.FAILURE;
        engine.log(a, 'DECISION', 'AI決策', '施放技能', `決定使用 ${a.skills[idx]!.name}`);
        return engine.performCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        // Charge logic
        const speedMult = skill.range <= 2 ? 2.5 : 1.0;

        if (a.targetHex) {
            if (!a.isMoving) engine.log(a, 'DECISION', 'AI決策', '戰術移動', `前往最佳施法位置`);
            return engine.movement.moveAgentToHex(a, a.targetHex, skill.range, engine, speedMult);
        }
        if (a.target) {
             if (!a.isMoving) engine.log(a, 'DECISION', 'AI決策', '戰術移動', `接近目標 ${a.target.id}`);
             return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        engine.movement.updateTarget(a, engine); 
        if (!a.target) return NodeState.FAILURE;

        const speedMult = skill.range <= 2 ? 2.5 : 1.0;
        if (!a.isMoving) engine.log(a, 'DECISION', 'AI決策', '追擊', `追擊最近目標 ${a.target.id}`);

        return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { ISO_SCALE_Y, THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

interface Point3D { x: number; y: number; z: number; }

// 1. STANDARD EXPLOSION
export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS' | 'GLOW') {
    const safeCount = Math.min((type === 'SPARK' || type === 'GLOW') ? 15 : 8, count);

    for (let i = 0; i < safeCount; i++) {
        const theta = Math.random() * Math.PI * 2;
        const phi = (Math.random() - 0.5) * Math.PI; 
        const spd = Math.random() * 200 * speed;

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;

        const cosPhi = Math.cos(phi);
        p.vx = Math.cos(theta) * cosPhi * spd;
        p.vy = Math.sin(theta) * cosPhi * spd;
        p.vz = Math.sin(phi) * spd + (100 * speed); 

        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = (type === 'GLOW' ? 25 : 8) * (Math.random() + 0.5);
        p.type = type; 
        p.delay = 0;
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 15;

        system.state.particles.push(p);
    }
}

// 2. COMPOSITE IMPACT SPAWNER
export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'BLAST' | 'SHOCKWAVE', life: number) {
    if (type === 'SHOCKWAVE') {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.life = life; p.maxLife = life;
        p.color = color; p.size = 50;
        p.type = 'SHOCKWAVE';
        system.state.particles.push(p);
        return;
    }

    // --- HEX BLAST ---
    // Only spawn Flash if life > 0.4 (Very High impact only)
    if (life > 0.4) {
        const flash = system.state.getParticle();
        flash.x = x; flash.y = y; flash.z = z + 10;
        flash.life = 0.15; flash.maxLife = 0.15;
        flash.color = '#ffffdd'; 
        flash.size = 50; 
        flash.type = 'BLAST'; 
        flash.rotation = Math.random() * Math.PI;
        system.state.particles.push(flash);
    }

    const halo = system.state.getParticle();
    halo.x = x; halo.y = y; halo.z = z + 10;
    halo.life = 0.3; halo.maxLife = 0.3;
    halo.color = color;
    halo.size = 80;
    halo.type = 'GLOW'; 
    halo.rotation = Math.random() * Math.PI;
    system.state.particles.push(halo);

    const sparkCount = 4 + Math.floor(Math.random() * 2); 
    for(let i=0; i<sparkCount; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z + 10;
        const angle = Math.random() * Math.PI * 2;
        const speed = 300 + Math.random() * 200; 
        const lift = 100 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = lift;
        p.life = 0.2 + Math.random() * 0.2; p.maxLife = p.life;
        p.color = color; p.size = 3 + Math.random() * 2; 
        p.type = 'SPARK'; 
        system.state.particles.push(p);
    }
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, z: number, color: string, life: number) {
    addImpact(system, x, y, z + 5, color, 'SHOCKWAVE', life);
}

// 🎯 NEW: LIGHTWEIGHT RIPPLE (No flash, no sparks, just a ring)
export function spawnRipple(system: VFXSystem, x: number, y: number, z: number, color: string, size: number = 50) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z + 5;
    p.life = 0.8; p.maxLife = 0.8;
    p.color = color; 
    p.size = size;
    p.type = 'SHOCKWAVE'; // Uses generic expanding ring texture
    p.vx = 0; p.vy = 0; p.vz = 0;
    system.state.particles.push(p);
}

// 🎯 NEW: SOFT STATUS POP (Glow that rises gently)
export function spawnSoftStatusEffect(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RIPPLE' | 'GLOW') {
    if (type === 'RIPPLE') {
        spawnRipple(system, x, y, z, color, 60);
    } else {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z + 20;
        p.vx = 0; p.vy = 0; p.vz = 40; // Slow rise
        p.life = 1.0; p.maxLife = 1.0;
        p.color = color;
        p.size = 40;
        p.type = 'GLOW';
        system.state.particles.push(p);
    }
}

// 🎯 REFACTORED BEAM: Uses explicit start/end 3D anchors like Projectiles
export function spawnBeam(system: VFXSystem, start: Point3D, end: Point3D, color: string, duration: number = 0.4, size: number = 4) {
    const p = system.state.getParticle();
    // Populate the new Projectile-mirroring fields
    p.sx = start.x; p.sy = start.y; p.sz = start.z;
    p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

    // Sort Key: Use Start Y
    p.x = start.x; p.y = start.y; p.z = start.z;

    p.life = duration; p.maxLife = duration; 
    p.color = color; p.size = size; 
    p.type = 'BEAM'; 
    p.locked = true;
    system.state.particles.push(p);
}

export function spawnDeathRay(system: VFXSystem, start: Point3D, end: Point3D, color: string) {
    const p = system.state.getParticle();
    p.sx = start.x; p.sy = start.y; p.sz = start.z;
    p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

    p.x = start.x; p.y = start.y; p.z = start.z;

    p.life = 0.5; p.maxLife = 0.5;
    p.color = color;
    p.size = 10;
    p.type = 'DEATH_RAY';
    p.locked = true;
    system.state.particles.push(p);
}

export function spawnConnectorSlash(system: VFXSystem, start: Point3D, end: Point3D, color: string) {
    const p = system.state.getParticle();
    p.sx = start.x; p.sy = start.y; p.sz = start.z;
    p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

    p.x = start.x; p.y = start.y; p.z = start.z;

    p.life = 0.2; p.maxLife = 0.2;
    p.color = color; p.size = 12;
    p.type = 'BEAM'; // Reusing beam logic for slash connector
    p.locked = true;
    system.state.particles.push(p);
}

export function spawnPhysicsSplatter(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string) {
    const impactAngle = Math.atan2(dirY, dirX);
    const mainCount = 4; // Reduced count
    for (let i = 0; i < mainCount; i++) {
        const spread = (Math.random() - 0.5) * 1.2; 
        const angle = impactAngle + spread;
        const speed = 200 + Math.random() * 200; 

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 150 + Math.random() * 150; 

        p.life = 0.3 + Math.random() * 0.2; p.maxLife = p.life;
        p.type = 'CHIP'; 
        p.color = color; 
        p.size = 2 + Math.random() * 2; 
        p.vRotation = (Math.random() - 0.5) * 30; 
        system.state.particles.push(p);
    }
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, z: number, team: Team, role: Role, impulseX: number = 0, impulseY: number = 0) {
    const assets = SpriteManager.getUnitImages(role, team);

    // 1. Core Components (Base & Icon)
    const base = system.state.getParticle();
    base.x = x; base.y = y; base.z = z + 10;
    base.vx = impulseX * 0.8; base.vy = impulseY * 0.8;
    base.vz = 150 + Math.random() * 100;
    base.life = 2.0; base.maxLife = 2.0;
    base.color = '#fff'; base.size = 50; 
    base.type = 'SPRITE'; base.image = assets.base;
    base.vRotation = (Math.random() - 0.5) * 10;
    system.state.particles.push(base);

    const icon = system.state.getParticle();
    icon.x = x; icon.y = y; icon.z = z + 40; 
    icon.vx = impulseX * 1.2; icon.vy = impulseY * 1.2;
    icon.vz = 300 + Math.random() * 200;
    icon.life = 2.0; icon.maxLife = 2.0;
    icon.color = '#fff'; icon.size = 64; 
    icon.type = 'SPRITE'; icon.image = assets.icon;
    icon.vRotation = (Math.random() - 0.5) * 20; 
    system.state.particles.push(icon);

    const theme = team === Team.BLUE ? THEME_IMPERIAL : THEME_COVENANT;
    const shardCount = 8;

    for(let i=0; i<shardCount; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20; 
        p.y = y + (Math.random()-0.5)*20; 
        p.z = z + 30;

        const a = Math.random() * Math.PI * 2;
        const s = 150 + Math.random() * 250;
        p.vx = Math.cos(a)*s + impulseX*0.5;
        p.vy = Math.sin(a)*s + impulseY*0.5;
        p.vz = 250 + Math.random()*250; 

        p.life = 1.5; p.maxLife = 1.5;
        p.type = 'SHARD'; 
        p.color = Math.random() > 0.4 ? theme.primary : theme.armorDark;
        p.size = 6 + Math.random()*8; 
        p.vRotation = (Math.random()-0.5)*30; 
        system.state.particles.push(p);
    }

    for(let i=0; i<5; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z + 30;
        const a = Math.random() * Math.PI * 2;
        const s = 50 + Math.random() * 100;
        p.vx = Math.cos(a)*s;
        p.vy = Math.sin(a)*s;
        p.vz = 50 + Math.random()*50;
        p.life = 0.8; p.maxLife = 0.8;
        p.type = 'SPARK';
        p.color = theme.secondary; 
        p.size = 3 + Math.random()*3;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, z: number, color: string) {
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = z;
    beam.life = 0.5; beam.maxLife = 0.5;
    beam.color = color; beam.size = 40; beam.type = 'PILLAR';
    beam.locked = true;
    system.state.particles.push(beam);
    spawnShockwave(system, x, y, z, color, 0.5);
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, z: number, color: string, type: string, duration: number, delay: number) {
    const count = 3; // Reduced from 5
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        const r = 20;
        const a = Math.random() * Math.PI * 2;
        const dist = Math.random() * r;

        p.x = x + Math.cos(a) * dist;
        p.y = y + Math.sin(a) * dist * ISO_SCALE_Y;
        p.z = z + 5;

        p.vx = (Math.random()-0.5) * 10;
        p.vy = (Math.random()-0.5) * 10;
        p.vz = 10 + Math.random() * 10; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 40 + Math.random() * 20; 
        p.type = 'SMOKE';
        p.delay = delay + (i * 0.1); 
        p.vRotation = (Math.random() - 0.5) * 5;
        system.state.particles.push(p);
    }
}

export function spawnCastBreak(system: VFXSystem, x: number, y: number, z: number, radiusTiles: number, color: string) {
    // 🔴 FIX: Completely removed 'addImpact' call.
    // Replaced with a simple, dark non-additive ring to indicate interruption without flash.

    // 1. Simple Ring (Outline only, no glow)
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z + 20;
    p.life = 0.5; p.maxLife = 0.5;
    p.color = color; p.size = 40;
    p.type = 'SHOCKWAVE'; 
    system.state.particles.push(p);

    // 2. Shatter Shards (Physical debris, no bloom)
    for(let i=0; i<4; i++) {
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = z + 30;
        const angle = Math.random() * Math.PI * 2;
        const speed = 150 + Math.random() * 100;
        s.vx = Math.cos(angle) * speed; 
        s.vy = Math.sin(angle) * speed;
        s.vz = 200 + Math.random() * 100; 
        s.life = 0.5; s.maxLife = 0.5;
        s.color = color; s.size = 3 + Math.random() * 3; 
        s.type = 'CHIP'; 
        system.state.particles.push(s);
    }
}

export function spawnGridImpact(system: VFXSystem, x: number, y: number, z: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.life = 1.0; p.maxLife = 1.0;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    p.locked = true;
    system.state.particles.push(p);
}

export function spawnBloodRitual(system: VFXSystem, x: number, y: number, z: number, color: string, scale: number) {
    addImpact(system, x, y, z, color, 'BLAST', 0.5);
    for(let i=0; i<8; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*30 * scale;
        p.y = y + (Math.random()-0.5)*30 * scale;
        p.z = z + 5;
        p.vx = (Math.random()-0.5)*20;
        p.vy = (Math.random()-0.5)*20;
        p.vz = 50 + Math.random() * 100;
        p.life = 1.5; p.maxLife = 1.5;
        p.color = color;
        p.size = 20 + Math.random() * 10;
        p.type = 'SMOKE';
        p.vRotation = (Math.random()-0.5)*5;
        system.state.particles.push(p);
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET, THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        if (!event.targetId) target.z = groundZ + 20;

        switch (event.type) {
            // --- BEAMS & CONNECTORS ---
            case 'VISUAL_SLASH':
                if (event.sourceId && event.targetId) {
                    Generic.spawnConnectorSlash(vfx, origin, target, event.color || '#fff');
                }
                break;

            case 'VISUAL_BEAM':
                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, origin, target, event.color || '#be123c');
                } else if (event.skill?.id === 'rb_u3') {
                    // Orbital - handled elsewhere
                } else {
                    Generic.spawnBeam(vfx, origin, target, event.color || '#fff');
                    Generic.spawnSoftStatusEffect(vfx, target.x, target.y, target.z, event.color || '#fff', 'GLOW');
                }
                break;

            // --- IMPACTS ---
            case 'DAMAGE': 
                // 🔴 FILTER: Strictly prevent damage splatters for WAVE skills or minor ticks
                const isWave = event.skill?.visual === 'WAVE';
                const isMinor = Math.abs(event.value || 0) < 20;

                // Do not spawn physics chips if it's a wave skill or tiny damage (DoT)
                if (!event.skill?.projectileSpeed && !isWave && !isMinor) {
                    this.handleDamageImpact(event, engine, vfx, target);
                }
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, vfx, grid, target, groundZ, camera); 
                } else {
                    // AOE Hit: Use soft ripple for non-lethal, small blast for lethal
                    // Double check WAVE tag here too
                    if (event.skill && (event.skill.visual === 'WAVE' || Math.abs(event.skill.power) < 50)) {
                        Generic.spawnRipple(vfx, event.pos.x, event.pos.y, groundZ, event.skill.color);
                    } else {
                        Generic.addImpact(vfx, event.pos.x, event.pos.y, groundZ + 10, event.skill?.color || '#fff', 'BLAST', 0.2);
                    }
                }
                break;

            // --- AOE & SKILLS ---
            case 'IMPACT_AOE':
                this.handleAOE(event, engine, vfx, grid, camera, groundZ);
                break;

            // --- UNITS ---
            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    Generic.spawnUnitShatter(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, origin.x, origin.y, origin.z, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                // 🔴 FIX: Using new simplified spawnCastBreak (No Blast)
                Generic.spawnCastBreak(vfx, origin.x, origin.y, origin.z, event.value || 1, event.color || '#fff');
                // Cap trauma addition to prevent infinite stacking in one frame
                // Since this runs per target broken, we keep it very low
                camera.addTrauma(0.02); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);

        return {
            x: defaultX,
            y: defaultY,
            z: terrainH 
        };
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, target: Point3D) {
        let dx = 0; let dy = -1;
        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const diffX = t.px - s.px; 
                const diffY = t.py - s.py;
                const len = Math.sqrt(diffX*diffX + diffY*diffY);
                if (len > 0) { dx = diffX/len; dy = diffY/len; }
                const isVictimBlue = t.team === Team.BLUE;
                const debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;

                Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, dx, dy, debrisColor);
                return;
            }
        }
        // Fallback for environment damage
        if (event.value && event.value < -20) {
            Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, 0, -1, event.color || '#94a3b8');
        }
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, target: Point3D, groundZ: number, camera: CameraSystem): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';
        const source = engine.agents.find(a => a.id === event.sourceId);

        // --- 🔴 THE FIX: STATUS INTERCEPTION ---
        // If the skill is low power (utility) or purely status-based, 
        // FORCE it to use the new lightweight "WAVE" or "GLOW" logic.
        const isLowImpact = skill ? (Math.abs(skill.power) < 50) : false;
        const isPureStatus = skill ? (skill.ccType === 'TAUNT' || skill.ccType === 'FEAR' || skill.effectType === 'MANA_RESTORE' || skill.effectType === 'MANA_BURN') : false;

        if (skill && (visualType === 'WAVE' || isPureStatus || (isLowImpact && visualType === 'SMASH'))) {
            const mode = (isPureStatus || visualType === 'WAVE') ? 'RIPPLE' : 'GLOW';
            Generic.spawnSoftStatusEffect(vfx, target.x, target.y, target.z, color, mode);
            return; // 🛑 STOP HERE: Do not spawn heavy impacts
        }

        if (isUlt && skill) {
            if (this.dispatchUltVFX(skill.id, target, color, engine, vfx, grid, camera, groundZ, event.sourceId)) {
                return;
            }
            camera.addTrauma(0.15); 
            const faction = source ? source.team : Team.BLUE;
            if (faction === Team.BLUE) Generic.addImpact(vfx, target.x, target.y, target.z, color, 'BLAST', 0.8);
            else Generic.spawnBloodRitual(vfx, target.x, target.y, target.z, color, 1.5);
        } else {
            // Standard Skills
            let dx = 0, dy = 0;
            let debrisColor = color; 
            if (event.targetId) {
                const t = engine.agents.find(a => a.id === event.targetId);
                if (t) {
                    const isVictimBlue = t.team === Team.BLUE;
                    debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;
                }
            }
            if (source) {
                const len = Math.sqrt((target.x - source.px)**2 + (target.y - source.py)**2) || 1;
                dx = (target.x - source.px) / len; dy = (target.y - source.py) / len;
            }

            if (visualType === 'SMASH') {
                if (skill?.type === 'AOE') {
                    // Further nerf for AOE Smash hits
                    Generic.addImpact(vfx, target.x, target.y, target.z, color, 'BLAST', 0.2); 
                } else {
                    Generic.addImpact(vfx, target.x, target.y, target.z, color, 'SHOCKWAVE', 0.4);
                }
                Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, dx, dy, debrisColor);
            } 
            else if (visualType === 'SLASH') {
                if (source) Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, dx, dy, debrisColor);
                else Generic.addImpact(vfx, target.x, target.y, target.z, color, 'BLAST', 0.3);
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, target.x, target.y, target.z, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, target.x, target.y, target.z, 5, color, 0.5, 1.0, 'SMOKE');
            }
            else {
                Generic.addImpact(vfx, target.x, target.y, target.z, color, 'BLAST', 0.3);
                if (dx !== 0 || dy !== 0) Generic.spawnPhysicsSplatter(vfx, target.x, target.y, target.z, dx, dy, debrisColor);
            }
        }
    }

    private handleAOE(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, groundZ: number) {
        if (!event.skill) return;
        const centerPt = { x: event.pos.x, y: event.pos.y, z: groundZ };
        const color = event.color || '#fff';

        // 🚨 ROUTING FIX: Try specific spawners first
        if (this.dispatchUltVFX(event.skill.id, centerPt, color, engine, vfx, grid, camera, groundZ, event.sourceId)) {
            return;
        }

        // --- NEW: LOW IMPACT AOE ---
        if (event.skill.visual === 'WAVE' || Math.abs(event.skill.power) < 50) {
            Generic.spawnRipple(vfx, event.pos.x, event.pos.y, groundZ, color, 120);
            return;
        }

        // Generic Grid Reaction (Fallback for standard AOEs)
        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const radius = event.skill.aoeRadius || 1;
        const affectedHexes = HexUtils.range(centerHex, radius);

        affectedHexes.forEach(h => {
            if (engine.map.isValid(h.q, h.r)) {
                const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                const dist = HexUtils.dist(centerHex, h);
                const delay = dist * 0.06;
                Generic.spawnGridImpact(vfx, tilePos.x, tilePos.y, hHeight, event.color || '#fff', Team.BLUE, delay);
            }
        });

        // Generic Core Impact
        Generic.addImpact(vfx, event.pos.x, event.pos.y, groundZ, event.color || '#fff', 'BLAST', 0.5);
        camera.addTrauma(0.15); // Reduced from 0.25
    }

